import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  Typography,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  IconButton,
  Alert,
  Snackbar,
} from '@mui/material';
import { Delete as DeleteIcon, Edit as EditIcon, CloudUpload as CloudUploadIcon } from '@mui/icons-material';
import { collection, addDoc, getDocs, doc, updateDoc, deleteDoc, query, where, writeBatch } from 'firebase/firestore';
import { db } from '../firebase';
import { Category } from '../types';
import { categories } from '../categories';
import { foodItems, FoodItem } from '../foodItems';

const MenuItems: React.FC = () => {
  const [items, setItems] = useState<FoodItem[]>([]);
  const [categoriesList, setCategories] = useState<Category[]>([]);
  const [open, setOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState<FoodItem | null>(null);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' as 'success' | 'error' });
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    category: '',
    imagePath: '',
  });

  useEffect(() => {
    fetchItems();
    fetchCategories();
  }, []);

  const fetchItems = async () => {
    const querySnapshot = await getDocs(collection(db, 'menuItems'));
    const itemsData = querySnapshot.docs.map(doc => ({
      id: parseInt(doc.id),
      ...doc.data()
    })) as FoodItem[];
    setItems(itemsData);
  };

  const fetchCategories = async () => {
    const querySnapshot = await getDocs(collection(db, 'categories'));
    const categoriesData = querySnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    })) as Category[];
    setCategories(categoriesData);
  };

  const handleOpen = (item?: FoodItem) => {
    if (item) {
      setSelectedItem(item);
      setFormData({
        name: item.name,
        description: item.description,
        price: item.price.toString(),
        category: item.category,
        imagePath: item.imagePath || '',
      });
    } else {
      setSelectedItem(null);
      setFormData({
        name: '',
        description: '',
        price: '',
        category: '',
        imagePath: '',
      });
    }
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setSelectedItem(null);
    setFormData({
      name: '',
      description: '',
      price: '',
      category: '',
      imagePath: '',
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const itemData = {
      name: formData.name,
      description: formData.description,
      price: parseFloat(formData.price),
      category: formData.category,
      imagePath: formData.imagePath,
    };

    try {
      if (selectedItem) {
        await updateDoc(doc(db, 'menuItems', selectedItem.id.toString()), itemData);
      } else {
        await addDoc(collection(db, 'menuItems'), itemData);
      }
      handleClose();
      fetchItems();
    } catch (error) {
      console.error('Error saving menu item:', error);
    }
  };

  const handleDelete = async (id: number) => {
    if (window.confirm('آیا از حذف این مورد اطمینان دارید؟')) {
      try {
        await deleteDoc(doc(db, 'menuItems', id.toString()));
        fetchItems();
      } catch (error) {
        console.error('Error deleting menu item:', error);
      }
    }
  };

  const handleImportData = async () => {
    try {
      const batch = writeBatch(db);

      // Import categories
      for (const category of categories) {
        const categoryRef = doc(collection(db, 'categories'));
        batch.set(categoryRef, {
          name: category.name,
          icon: category.icon,
        });
      }

      // Import food items
      for (const item of foodItems) {
        const itemRef = doc(collection(db, 'menuItems'));
        batch.set(itemRef, {
          name: item.name,
          description: item.description,
          price: item.price,
          category: item.category,
          imagePath: item.imagePath || '',
        });
      }

      await batch.commit();
      setSnackbar({
        open: true,
        message: 'داده‌ها با موفقیت وارد شدند',
        severity: 'success'
      });

      // Refresh the data
      fetchItems();
      fetchCategories();
    } catch (error) {
      console.error('Error importing data:', error);
      setSnackbar({
        open: true,
        message: 'خطا در وارد کردن داده‌ها',
        severity: 'error'
      });
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4" component="h1">
          موارد منو
        </Typography>
        <Box sx={{ display: 'flex', gap: 2 }}>
          {/*<Button
            variant="outlined"
            color="primary"
            startIcon={<CloudUploadIcon />}
            onClick={handleImportData}
          >
            وارد کردن داده‌های اولیه
          </Button>
          */}<Button variant="contained" color="primary" onClick={() => handleOpen()}>
            افزودن مورد جدید
          </Button>
        </Box>
      </Box>

      {categoriesList.map((category) => {
        const categoryItems = items.filter(item => item.category === category.name);
        if (categoryItems.length === 0) return null;

        return (
          <Box key={category.id} sx={{ mb: 4 }}>
            <Typography variant="h5" component="h2" sx={{ mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
              {category.icon && <span>{category.icon}</span>}
              {category.name}
            </Typography>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 3 }}>
              {categoryItems.map((item) => (
                <Box
                  key={item.id}
                  sx={{
                    width: { xs: '100%', sm: 'calc(50% - 12px)', md: 'calc(33.33% - 16px)' },
                    minWidth: 300,
                  }}
                >
                  <Card>
                    <CardContent>
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <Box>
                          <Typography variant="h6" component="div">
                            {item.name}
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {item.description}
                          </Typography>
                          <Typography variant="h6" color="primary" sx={{ mt: 1 }}>
                            {item.price.toLocaleString()} تومان
                          </Typography>
                        </Box>
                        <Box>
                          <IconButton onClick={() => handleOpen(item)} size="small">
                            <EditIcon />
                          </IconButton>
                          <IconButton onClick={() => handleDelete(item.id)} size="small" color="error">
                            <DeleteIcon />
                          </IconButton>
                        </Box>
                      </Box>
                    </CardContent>
                  </Card>
                </Box>
              ))}
            </Box>
          </Box>
        );
      })}

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>
          {selectedItem ? 'ویرایش مورد منو' : 'افزودن مورد جدید'}
        </DialogTitle>
        <form onSubmit={handleSubmit}>
          <DialogContent>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
              <TextField
                fullWidth
                label="نام"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
              />
              <TextField
                fullWidth
                label="توضیحات"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                multiline
                rows={3}
              />
              <TextField
                fullWidth
                label="قیمت"
                type="number"
                value={formData.price}
                onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                required
              />
              <FormControl fullWidth>
                <InputLabel>دسته‌بندی</InputLabel>
                <Select
                  value={formData.category}
                  onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                  required
                >
                  {categoriesList.map((category) => (
                    <MenuItem key={category.id} value={category.name}>
                      {category.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Box>
          </DialogContent>
          <DialogActions>
            <Button onClick={handleClose}>انصراف</Button>
            <Button type="submit" variant="contained" color="primary">
              {selectedItem ? 'ذخیره تغییرات' : 'افزودن'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default MenuItems;
